{"packet_id": "D067-02", "doc_id": "D067", "jurisdiction": "NJ", "category": "security_deposits", "lifecycle": "enacted", "title": "New owner's duty on transfer of the property", "requirement": "When rental property is sold or transferred, the new owner must obtain the tenant's security deposit plus accrued interest and is responsible for investing it, giving notices, paying interest, and returning it.", "key_value": "security deposit plus accrued interest", "coverage_conditions": "Residential tenancies whose security deposit was collected by a former owner when the property is sold or transferred.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "N.J.S.A. 46:8-21", "quoted_span": "If the property is sold or transferred it is the duty of the new owner to obtain the security deposit, plus accrued interest on the tenant’s deposit, that was collected by the former owner.", "interaction": null, "confidence": 0.8, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D067-02", "doc_id": "D067", "jurisdiction": "NJ", "category": "security_deposits", "lifecycle": "enacted", "title": "Penalty for withholding a subsidized tenant's deposit", "requirement": "A landlord who willfully and intentionally withholds the security deposit of a tenant who received State or federal financial assistance, including welfare or rental assistance, is liable for a civil penalty for each offense.", "key_value": "$500 to $2,000 per offense", "coverage_conditions": "Security deposits made by or on behalf of tenants who received financial assistance through any State or federal program, including welfare or rental assistance.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": "Civil penalty of not less than $500 and not more than $2,000 per offense, collected by summary proceedings; the State entity that made the deposit is entitled to the penalty recovered.", "effective_date": null, "citation": "N.J.S.A. 46:8-21.5", "quoted_span": "Any landlord who willfully and intentionally withholds a security deposit made by or on behalf of a tenant who has received financial assistance through any Stat e or federal program, including welfare or rental assistance , may be penalized. The landlord may be liable for a civil penalty of not less than $500 or not more than $2,000 for each offense.", "interaction": null, "confidence": 0.8, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D067-02", "doc_id": "D067", "jurisdiction": "NJ", "category": "security_deposits", "lifecycle": "enacted", "title": "Unlawful use of security deposit money", "requirement": "No person may unlawfully use security deposit money; a violation is a disorderly persons offense punishable by fine, imprisonment, or both.", "key_value": "fine of at least $200, up to 30 days imprisonment", "coverage_conditions": "Any person who receives or holds security deposit money for a residential tenancy.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": "Charged as a disorderly person: fine of not less than $200 or imprisonment for not more than 30 days, or both.", "effective_date": null, "citation": "N.J.S.A. 46:8-25", "quoted_span": "Any person who unlawfully uses security deposit monies may be c riminally charged as a disorderly person and may be subject to a fine of not less than $200 or imprisonment for not more than 30 days, or both (N.J.S.A. 46:8-25).", "interaction": null, "confidence": 0.8, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D067-02", "doc_id": "D067", "jurisdiction": "NJ", "category": "rent_increase_limits", "lifecycle": "enacted", "title": "Newly constructed multiple dwellings exempt from local rent control", "requirement": "Newly constructed multiple dwellings are exempt from any municipal rent control or rent leveling ordinance for 30 years after completion of construction of the building.", "key_value": "30 years following completion of construction", "coverage_conditions": "Newly constructed multiple dwellings; rents subsidized by governmental funding may also be exempt from local rent control ordinances.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": "construction_date", "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": "Newly constructed multiple dwellings, and rents subsidized by governmental funding, are exempt from municipal rent control ordinances.", "penalty": null, "effective_date": null, "citation": "N.J.S.A. 2A:42-84.5", "quoted_span": "Under the Newly Constructed Multiple Dwellings Law ( N.J.S.A. 2A:42 -84.5), newly constructed multiple dwellings shall be exempt from any local rent control ordinances for a period of 30 years following completion of construction of the building.", "interaction": null, "confidence": 0.8, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D067-02", "doc_id": "D067", "jurisdiction": "NJ", "category": "rent_increase_limits", "lifecycle": "enacted", "title": "Unconscionable rent increase barred under the Anti-Eviction Act", "requirement": "Before evicting for nonpayment of a rent increase the landlord must serve a valid notice to quit and notice of rent increase, and the increase must not be unconscionable or violate a municipal rent ordinance.", "key_value": "rent increase must not be unconscionable", "coverage_conditions": "Residential tenancies covered by the Anti-Eviction Act; a landlord may raise rent only by terminating the old lease and offering a new lease at the increased rent.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": "The tenant may file a complaint with a municipal rent control board where one exists; otherwise a judge decides whether the increase is unconscionable in the eviction action.", "effective_date": null, "citation": "N.J.S.A. 2A:18-61.1", "quoted_span": "The increase in rent must not be unconscionable; it must not be so unreasonable as to shock the conscience of a fair and honest person and must comply with any municipal ordinances governing rent increases.", "interaction": "The increase must comply with any municipal ordinances governing rent increases where such ordinances exist.", "confidence": 0.8, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D067-02", "doc_id": "D067", "jurisdiction": "NJ", "category": "rent_increase_limits", "lifecycle": "enacted", "title": "No rent increase to cover condominium or cooperative conversion costs", "requirement": "When a building is converted to condominium, cooperative, or fee simple ownership of units, the landlord may not raise rents to cover costs resulting solely from the conversion.", "key_value": null, "coverage_conditions": "All tenants in a converted building, whether or not they are eligible for protected tenancy as senior citizens or disabled persons.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": "Rents may still be increased to cover the cost of new services or amenities.", "penalty": null, "effective_date": null, "citation": "N.J.S.A. 2A:18-61.31", "quoted_span": "If a building is converted to a condominium or cooperative form of ownership, or to fee simple ownership of units, rents may not be increased to cover cos ts resulting solely from the conversion (N.J.S.A. 2A:18-61.31).", "interaction": null, "confidence": 0.8, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D067-02", "doc_id": "D067", "jurisdiction": "NJ", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "Anti-Eviction Act good cause requirement", "requirement": "No residential landlord may evict a tenant or fail to renew a lease, written or oral, without good cause, and the landlord must be able to prove the grounds for eviction in court.", "key_value": null, "coverage_conditions": "Residential tenants protected by the Anti-Eviction Act, N.J.S.A. 2A:18-61.1 to 61.12; a landlord may recover possession only by tenant consent or the legal eviction process.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "N.J.S.A. 2A:18-61.1", "quoted_span": "No residential landlord may evict or fail to renew a lease, whether it is a written or an oral lease without good cause. The landlord must be able to prove in court that he has grounds for an eviction.", "interaction": null, "confidence": 0.8, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D067-02", "doc_id": "D067", "jurisdiction": "NJ", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "Notice to Quit required for good cause evictions", "requirement": "For every good cause eviction except nonpayment of rent, the landlord must describe the cause in detail in a written notice to the tenant and serve a Notice to Quit; a Notice to Cease may also be required.", "key_value": null, "coverage_conditions": "All good cause evictions of residential tenants; the notice requirement does not apply to evictions for nonpayment of rent.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": "No Notice to Quit is required for an eviction for nonpayment of rent.", "penalty": null, "effective_date": null, "citation": "N.J.S.A. 2A:18-61.2", "quoted_span": "Each cause, except for nonpayment of rent, must be described in detail by the landlord in a written notice to the tenant. A “Notice to Quit” is required for all good cause evictions, except for an eviction for nonpayment of rent ( N.J.S.A. 2A:18-61.2).", "interaction": null, "confidence": 0.8, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D067-02", "doc_id": "D067", "jurisdiction": "NJ", "category": "screening_restrictions", "lifecycle": "enacted", "title": "Law Against Discrimination source-of-income protection", "requirement": "A landlord must treat applicants and tenants equally in the rental of housing and may not discriminate on the basis of source of lawful income, along with the other protected characteristics listed in the Law Against Discrimination.", "key_value": null, "coverage_conditions": "All landlord-tenant relationships in New Jersey, with exceptions for two-family owner-occupied dwellings and rooms in an owner- or resident-occupied single home.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": true, "other": null}, "exemptions": "Two-family owner-occupied dwellings; rooms in an owner- or resident-occupied single home; residences planned exclusively for and occupied by one sex, as it pertains to familial status.", "penalty": "Landlords who violate the Law Against Discrimination are subject to fines and penalties up to $10,000 for a first offense.", "effective_date": null, "citation": "N.J.S.A. 10:5-12", "quoted_span": "prohibits discrimination when selling or renting property and requires equal treatment in the sale or rental of housing regardless of race, creed, color, national origin, ancestry, sex, marital status, civil union status, domestic partnership status, familial status, affectional or sexual orientation, gender  identity or expression, mental and physical disability, nationality, or source of lawful income.", "interaction": null, "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D067-02", "doc_id": "D067", "jurisdiction": "NJ", "category": "application_screening_fees", "lifecycle": "enacted", "title": "Tenant-paid credit report cost and application fees", "requirement": "A landlord may charge an applicant the cost of a credit report and may also request reasonable rental application fees or employment verification; no dollar cap is stated in the guide.", "key_value": "cost of the credit report; reasonable application fees", "coverage_conditions": "Prospective residential tenants screened through credit bureaus or tenant screening agencies in New Jersey.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "Truth in Renting: Credit Checks and Background Checks", "quoted_span": "The landlord is allowed to charge the tenant for the cost of the report. The landlord may also request reasonable rental application fees or employment verification.", "interaction": null, "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
